import random

def ruin_probability(i, N, p, trials=20000):
    ruined = 0
    for _ in range(trials):
        bank = i
        while 0 < bank < N:
            bank += 1 if random.random() < p else -1
        ruined += bank == 0
    return 1 - ruined / trials   # P(reach N before 0)

print(round(ruin_probability(10, 100, 0.49), 3))    # ~0.009
print(round(ruin_probability(10, 100, 0.5), 3))     # ~0.100

